import React, { useState, useMemo } from "react";
import { DollarSign, Calendar, TrendingUp, Layers, Trash2 } from "lucide-react";

const CATEGORIES = [
  { name: "Food", color: "#F4A259" },
  { name: "Travel", color: "#5B8DEF" },
  { name: "Shopping", color: "#9B72CF" },
  { name: "Bills", color: "#4CAF8C" },
  { name: "Health", color: "#EF6C6C" },
  { name: "Other", color: "#8C97A8" },
];

function categoryColor(name) {
  return CATEGORIES.find((c) => c.name === name)?.color || "#8C97A8";
}

function todayISO() {
  return new Date().toISOString().slice(0, 10);
}

function formatDate(iso) {
  const d = new Date(iso + "T00:00:00");
  return d.toLocaleDateString("en-GB", { day: "2-digit", month: "short", year: "numeric" });
}

export default function ExpenseTracker() {
  const [expenses, setExpenses] = useState([]);
  const [amount, setAmount] = useState("");
  const [category, setCategory] = useState("");
  const [description, setDescription] = useState("");
  const [date, setDate] = useState(todayISO());
  const [error, setError] = useState("");

  const stats = useMemo(() => {
    let total = 0, month = 0, week = 0, today = 0;
    const nowTime = new Date();
    const startOfWeek = new Date(nowTime);
    startOfWeek.setDate(nowTime.getDate() - nowTime.getDay());
    startOfWeek.setHours(0, 0, 0, 0);

    expenses.forEach((e) => {
      const d = new Date(e.date + "T00:00:00");
      total += e.amount;
      if (d.getMonth() === nowTime.getMonth() && d.getFullYear() === nowTime.getFullYear()) {
        month += e.amount;
      }
      if (d >= startOfWeek) {
        week += e.amount;
      }
      if (e.date === todayISO()) {
        today += e.amount;
      }
    });
    return { total, month, week, today };
  }, [expenses]);

  function handleAdd(e) {
    e.preventDefault();
    const value = parseFloat(amount);
    if (!value || value <= 0) {
      setError("Enter a valid amount");
      return;
    }
    if (!category) {
      setError("Choose a category");
      return;
    }
    setExpenses((prev) => [
      {
        id: Date.now(),
        amount: value,
        category,
        description: description.trim() || category,
        date,
      },
      ...prev,
    ]);
    setAmount("");
    setCategory("");
    setDescription("");
    setDate(todayISO());
    setError("");
  }

  function removeExpense(id) {
    setExpenses((prev) => prev.filter((e) => e.id !== id));
  }

  const statCards = [
    { label: "Total Expense", value: stats.total, icon: DollarSign },
    { label: "This Month", value: stats.month, icon: Calendar },
    { label: "This Week", value: stats.week, icon: TrendingUp },
    { label: "Today", value: stats.today, icon: Layers },
  ];

  return (
    <div className="min-h-screen bg-slate-50 py-10 px-4">
      <div className="max-w-5xl mx-auto">
        {/* Header */}
        <div className="text-center mb-8">
          <h1 className="text-4xl font-serif font-bold text-indigo-600 tracking-tight">
            Expense Tracker
          </h1>
          <p className="text-slate-500 mt-1">Keep track of your spending and manage your budget</p>
        </div>

        {/* Stat cards */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
          {statCards.map(({ label, value, icon: Icon }) => (
            <div
              key={label}
              className="bg-white rounded-xl border border-slate-200 px-5 py-4 flex items-center justify-between shadow-sm"
            >
              <div>
                <p className="text-xs text-slate-500">{label}</p>
                <p className="text-xl font-bold text-slate-800">${value.toFixed(2)}</p>
              </div>
              <div className="w-9 h-9 rounded-full bg-indigo-50 flex items-center justify-center text-indigo-500">
                <Icon size={16} />
              </div>
            </div>
          ))}
        </div>

        <div className="grid md:grid-cols-2 gap-6">
          {/* Add expense form */}
          <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-6">
            <h2 className="font-serif font-bold text-lg text-slate-800 mb-5">Add New Expense</h2>
            <form onSubmit={handleAdd} className="space-y-4">
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-sm text-slate-600 block mb-1">Amount ($)</label>
                  <input
                    type="number"
                    step="0.01"
                    placeholder="0.00"
                    value={amount}
                    onChange={(e) => setAmount(e.target.value)}
                    className="w-full px-3 py-2 rounded-lg border border-slate-300 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-400"
                  />
                </div>
                <div>
                  <label className="text-sm text-slate-600 block mb-1">Category</label>
                  <select
                    value={category}
                    onChange={(e) => setCategory(e.target.value)}
                    className="w-full px-3 py-2 rounded-lg border border-slate-300 text-sm bg-white focus:outline-none focus:ring-2 focus:ring-indigo-400"
                  >
                    <option value="">Select category</option>
                    {CATEGORIES.map((c) => (
                      <option key={c.name} value={c.name}>
                        {c.name}
                      </option>
                    ))}
                  </select>
                </div>
              </div>

              <div>
                <label className="text-sm text-slate-600 block mb-1">Description</label>
                <input
                  type="text"
                  placeholder="What did you spend on?"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  className="w-full px-3 py-2 rounded-lg border border-slate-300 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-400"
                />
              </div>

              <div>
                <label className="text-sm text-slate-600 block mb-1">Date</label>
                <input
                  type="date"
                  value={date}
                  onChange={(e) => setDate(e.target.value)}
                  className="w-full px-3 py-2 rounded-lg border border-slate-300 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-400"
                />
              </div>

              {error && <p className="text-sm text-red-500">{error}</p>}

              <button
                type="submit"
                className="w-full py-2.5 rounded-lg bg-indigo-600 text-white font-semibold text-sm hover:bg-indigo-700 transition-colors"
              >
                Add Expense
              </button>
            </form>
          </div>

          {/* Recent expenses */}
          <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-6">
            <h2 className="font-serif font-bold text-lg text-slate-800 mb-5">Recent Expenses</h2>
            {expenses.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-16 text-slate-300">
                <DollarSign size={28} className="mb-2" />
                <p className="text-sm text-slate-400">No expenses yet. Add your first expense above!</p>
              </div>
            ) : (
              <ul className="divide-y divide-slate-100 max-h-96 overflow-y-auto">
                {expenses.map((e) => (
                  <li key={e.id} className="flex items-center justify-between py-3 group">
                    <div className="flex items-center gap-3">
                      <span
                        className="w-2.5 h-2.5 rounded-full shrink-0"
                        style={{ backgroundColor: categoryColor(e.category) }}
                      />
                      <div>
                        <p className="text-sm font-medium text-slate-800">{e.description}</p>
                        <p className="text-xs text-slate-400">
                          {e.category} · {formatDate(e.date)}
                        </p>
                      </div>
                    </div>
                    <div className="flex items-center gap-3">
                      <span className="text-sm font-semibold text-slate-800">
                        ${e.amount.toFixed(2)}
                      </span>
                      <button
                        onClick={() => removeExpense(e.id)}
                        className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                        aria-label="Delete expense"
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
